 16	type (
 17		// GzipConfig defines the config for Gzip middleware.
 18		GzipConfig struct {
 19			// Skipper defines a function to skip middleware.
 20			Skipper Skipper
 21	
 22			// Gzip compression level.
 23			// Optional. Default value -1.
