 25		}
 26	
 27		gzipResponseWriter struct {
 28			io.Writer
 29			http.ResponseWriter
 30		}
 31	)
 32	
 33	const (
 34		gzipScheme = "gzip"
 35	)
 36	
 37	var (
 38		// DefaultGzipConfig is the default Gzip middleware config.
 39		DefaultGzipConfig = GzipConfig{
 40			Skipper: DefaultSkipper,
 41			Level:   -1,
 42		}
 43	)
 44	
 45	// Gzip returns a middleware which compresses HTTP response using gzip compression
 46	// scheme.
 47	func Gzip() echo.MiddlewareFunc {
 48		return GzipWithConfig(DefaultGzipConfig)
 49	}
 50	
 51	// GzipWithConfig return Gzip middleware with config.
 52	// See: `Gzip()`.
 53	func GzipWithConfig(config GzipConfig) echo.MiddlewareFunc {
 54		// Defaults
 55		if config.Skipper == nil {
 56			config.Skipper = DefaultGzipConfig.Skipper
 57		}
 58		if config.Level == 0 {
 59			config.Level = DefaultGzipConfig.Level
 60		}
 61	
 62		pool := gzipCompressPool(config)
 63	
 64		return func(next echo.HandlerFunc) echo.HandlerFunc {
 65			return func(c echo.Context) error {
 66				if config.Skipper(c) {
 67					return next(c)
 68				}
 69	
 70				res := c.Response()
 71				res.Header().Add(echo.HeaderVary, echo.HeaderAcceptEncoding)
 72				if strings.Contains(c.Request().Header.Get(echo.HeaderAcceptEncoding), gzipScheme) {
 73					res.Header().Set(echo.HeaderContentEncoding, gzipScheme) // Issue #806
 74					i := pool.Get()
 75					w, ok := i.(*gzip.Writer)
 76					if !ok {
 77						return echo.NewHTTPError(http.StatusInternalServerError, i.(error).Error())
 78					}
 79					rw := res.Writer
 80					w.Reset(rw)
 81					defer func() {
 82						if res.Size == 0 {
 83							if res.Header().Get(echo.HeaderContentEncoding) == gzipScheme {
 84								res.Header().Del(echo.HeaderContentEncoding)
 85							}
 86							// We have to reset response to it's pristine state when
 87							// nothing is written to body or error is returned.
 88							// See issue #424, #407.
 89							res.Writer = rw
 90							w.Reset(ioutil.Discard)
 91						}
 92						w.Close()
 93						pool.Put(w)
 94					}()
 95					grw := &gzipResponseWriter{Writer: w, ResponseWriter: rw}
 96					res.Writer = grw
 97				}
 98				return next(c)
 99			}
100		}
101	}
102	
103	func (w *gzipResponseWriter) WriteHeader(code int) {
104		if code == http.StatusNoContent { // Issue #489
105			w.ResponseWriter.Header().Del(echo.HeaderContentEncoding)
106		}
107		w.Header().Del(echo.HeaderContentLength) // Issue #444
108		w.ResponseWriter.WriteHeader(code)
109	}
110	
111	func (w *gzipResponseWriter) Write(b []byte) (int, error) {
112		if w.Header().Get(echo.HeaderContentType) == "" {
113			w.Header().Set(echo.HeaderContentType, http.DetectContentType(b))
114		}
115		return w.Writer.Write(b)
116	}
117	
118	func (w *gzipResponseWriter) Flush() {
119		w.Writer.(*gzip.Writer).Flush()
120		if flusher, ok := w.ResponseWriter.(http.Flusher); ok {
121			flusher.Flush()
122		}
123	}
124	
125	func (w *gzipResponseWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
126		return w.ResponseWriter.(http.Hijacker).Hijack()
127	}
128	
129	func (w *gzipResponseWriter) Push(target string, opts *http.PushOptions) error {
130		if p, ok := w.ResponseWriter.(http.Pusher); ok {
131			return p.Push(target, opts)
132		}
133		return http.ErrNotSupported
134	}
135	
136	func gzipCompressPool(config GzipConfig) sync.Pool {
137		return sync.Pool{
138			New: func() interface{} {
139				w, err := gzip.NewWriterLevel(ioutil.Discard, config.Level)
140				if err != nil {
141					return err
142				}
143				return w
144			},
145		}
146	}

