func TestZZScratchFuzz(t *testing.T) {
	pool := []string{"/", "/*", "/a", "/a/*", "/:id", "/a/:id", "/a/b", "/a/b/*", "/:id/b", "/a/:id/*", "/:id/*", "/a/b/:c"}
	queries := []string{"", "/", "/a", "/a/", "//", "/a/b", "/a/b/c", "/x", "/x/y", "/a/b/", "/a/b/c/d"}
	var panics []string
	// single routes
	for _, r1 := range pool {
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					panics = append(panics, fmt.Sprintf("ADD %q panic: %v", r1, rec))
				}
			}()
			e := New()
			e.GET(r1, func(c Context) error { return nil })
			for _, q := range queries {
				func() {
					defer func() {
						if rec := recover(); rec != nil {
							panics = append(panics, fmt.Sprintf("route %q find %q panic: %v", r1, q, rec))
						}
					}()
					c := e.NewContext(nil, nil)
					e.router.Find(http.MethodGet, q, c)
					_ = c.Handler()(c)
				}()
			}
		}()
	}
	// pairs
	for _, r1 := range pool {
		for _, r2 := range pool {
			if r1 == r2 {
				continue
			}
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						panics = append(panics, fmt.Sprintf("ADD %q,%q panic: %v", r1, r2, rec))
					}
				}()
				e := New()
				e.GET(r1, func(c Context) error { return nil })
				e.GET(r2, func(c Context) error { return nil })
				for _, q := range queries {
					func() {
						defer func() {
							if rec := recover(); rec != nil {
								panics = append(panics, fmt.Sprintf("routes %q,%q find %q panic: %v", r1, r2, q, rec))
							}
						}()
						c := e.NewContext(nil, nil)
						e.router.Find(http.MethodGet, q, c)
						_ = c.Handler()(c)
					}()
				}
			}()
		}
	}
	for i, p := range panics {
		if i > 40 {
			t.Logf("... %d more", len(panics)-i)
			break
		}
		t.Logf("PANIC: %s", p)
	}
	t.Logf("total panics: %d", len(panics))
}
