	for _, sub := range subsets {
		e := New()
		addPanic := false
		for _, rt := range sub {
			if msg, st := func() (interface{}, string) {
				defer func() {
					if r := recover(); r != nil {
						_ = r
					}
				}()
				return nil, ""
			}(); msg != nil {
				_ = st
			}
			func() {
