			panics++
			continue
		}
		for _, p := range reqPaths {
			msg, st := findPanic(e, http.MethodGet, p)
			if msg != nil {
				fmt.Printf("FINDPANIC routes=%v path=%q: %v [%s]\n", sub, p, msg, topRouterLine(st))
				panics++
			}
		}
	}
	fmt.Printf("TOTAL PANICS: %d\n", panics)
