func describe(e *Echo, method, path string) string {
	defer func() {
		if r := recover(); r != nil {
			fmt.Printf("   PANIC find(%q): %v\n", path, r)
		}
	}()
	c := e.NewContext(nil, nil).(*context)
	e.Router().Find(method, path, c)
	kind := "nil"
	if c.handler == nil {
		kind = "nil"
	} else {
		err := c.handler(c)
		switch {
		case err == ErrNotFound:
			kind = "NotFound"
		case err == ErrMethodNotAllowed:
			kind = "MethodNotAllowed"
		case err == nil:
			kind = fmt.Sprintf("ROUTE(path=%q pnames=%v pvalues=%v)", c.Path(), c.pnames, c.pvalues)
		default:
			kind = fmt.Sprintf("handler-err=%v", err)
		}
	}
	return kind
}

