package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

func segs(p string) []string {
	if p == "/" || p == "" {
		return nil
	}
	p = strings.TrimPrefix(p, "/")
	return strings.Split(p, "/")
}

// patternMatches implements echo's documented route matching semantics:
// static segment == segment, :param matches exactly one segment, * matches rest (0+ segments)
func patternMatches(pattern, path string) bool {
	pp := segs(pattern)
	sp := segs(path)
	i := 0
	for ; i < len(pp); i++ {
		if pp[i] == "*" {
			return true
		}
		if i >= len(sp) {
			return false
		}
		if strings.HasPrefix(pp[i], ":") {
			continue
		}
		if pp[i] != sp[i] {
			return false
		}
	}
	return len(pp) == len(sp)
}

func TestZZInvariant(t *testing.T) {
	tmpl := []string{
		"/", "/a", "/a/b", "/a/b/c", "/:p", "/:p/x", "/:p/:q", "/a/:p", "/a/:p/b", "/a/b/:p",
		"/*", "/a/*", "/:p/*", "/a/:p/*", "/a/b/*", "/x/*/y", "/a/*/b", "/a/", "/a/b/", "/:p/", "/a/:p/", "/:p/b", "/:p/b/c", "/a/:p/c",
	}
	reqs := []string{
		"", "/", "//", "///", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/d", "/a/b/c/d/e",
		"/a/x", "/x", "/x/y", "/a/x/y", "/a/b/x", "/a/b/x/y", "/a/x/b", "/a/x/c", "/x/y/z",
		"*", "/*", "/:p", "/%2F", "/a//b", "////", "/a/b/c/d/e/f/g", "/a/b/c/d/e/f/g/h",
	}
	n := len(tmpl)
	bad := 0
	check := func(routes []string, path string) {
		e := New()
		for _, rt := range routes {
			e.Router().Add(http.MethodGet, rt, handlerFunc)
		}
		c := e.NewContext(nil, nil).(*context)
		e.Router().Find(http.MethodGet, path, c)
		matched := c.Path() // ctx.path == currentNode.ppath when a route matched
		if c.handler == nil {
			return
		}
		// handler is the route handler (not NotFound/MethodNotAllowed) -> check pattern
		if matched == "" {
			return
		}
		if !patternMatches(matched, path) {
			fmt.Printf("MISMATCH routes=%v path=%q matched=%q\n", routes, path, matched)
			bad++
		}
	}
	var subsets [][]string
	for i := 0; i < n; i++ {
		subsets = append(subsets, []string{tmpl[i]})
		for j := i + 1; j < n; j++ {
			subsets = append(subsets, []string{tmpl[i], tmpl[j]})
			for k := j + 1; k < n; k++ {
				subsets = append(subsets, []string{tmpl[i], tmpl[j], tmpl[k]})
				for l := k + 1; l < n; l++ {
					subsets = append(subsets, []string{tmpl[i], tmpl[j], tmpl[k], tmpl[l]})
				}
			}
		}
	}
	for _, sub := range subsets {
		for _, p := range reqs {
			check(sub, p)
		}
	}
	fmt.Printf("subsets=%d MISMATCHES=%d\n", len(subsets), bad)

	// random
	r := rand.New(rand.NewSource(7))
	for it := 0; it < 100000; it++ {
		nr := 1 + r.Intn(5)
		routes := make([]string, 0, nr)
		for i := 0; i < nr; i++ {
			routes = append(routes, randPath(r))
		}
		for i := 0; i < 3; i++ {
			check(routes, randPath(r))
		}
	}
	fmt.Printf("random done, total MISMATCHES=%d\n", bad)
}
