func TestZZTmpGzipEmpty(t *testing.T) {
	handlers := map[string]echo.HandlerFunc{
		"noContent200": func(c echo.Context) error { return c.NoContent(http.StatusOK) },
		"noContent204": func(c echo.Context) error { return c.NoContent(http.StatusNoContent) },
		"noContent304": func(c echo.Context) error { return c.NoContent(http.StatusNotModified) },
		"nilReturn":    func(c echo.Context) error { return nil },
		"emptyString":  func(c echo.Context) error { _, err := c.Response().Write([]byte("")); return err },
		"emptyBytes":   func(c echo.Context) error { _, err := c.Response().Write([]byte{}); return err },
		"statusOnly":   func(c echo.Context) error { c.Response().WriteHeader(http.StatusOK); return nil },
	}
	for name, h := range handlers {
		e := echo.New()
		e.Use(Gzip())
		e.GET("/", h)
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		body := rec.Body.Bytes()
		ce := rec.Header().Get(echo.HeaderContentEncoding)
		t.Logf("%s: code=%d ce=%q bodyLen=%d body=%q", name, rec.Code, ce, len(body), body)
		if ce == gzipScheme {
			r, err := gzip.NewReader(bytes.NewReader(body))
			if err != nil {
				t.Errorf("%s: Content-Encoding gzip but gzip.NewReader failed: %v (body %q)", name, err, body)
				continue
			}
			out, err := ioutil.ReadAll(r)
			r.Close()
			if err != nil {
				t.Errorf("%s: decoding gzip body failed: %v", name, err)
				continue
			}
			if len(out) != 0 {
				t.Errorf("%s: expected empty decoded body, got %q", name, out)
			}
		} else if len(body) != 0 {
			t.Errorf("%s: no Content-Encoding but non-empty body %q", name, body)
		}
	}
}
