func (b *DefaultBinder) bindData(destination interface{}, data map[string][]string, tag string) error {
	if destination == nil || len(data) == 0 {
		return nil
	}
	typ := reflect.TypeOf(destination).Elem()
	val := reflect.ValueOf(destination).Elem()

	// Support binding to limited Map destinations:
	// - map[string][]string,
	// - map[string]string <-- (binds first value from data slice)
	// - map[string]interface{} <-- (binds slice of values to interface type)
	// - map[string]bool <-- (binds first value from data slice)
	// - map[string]int <-- (binds first value from data slice)
	// - map[string]int8, int16, int32, int64
	// - map[string]uint, uint8, uint16, uint32, uint64
	// - map[string]float32, float64
	// - map[string]time.Time
	// - map[string]json.Number
	if typ.Kind() == reflect.Map && typ.Key().Kind() == reflect.String {
		// only allow maps with string keys
		elemKind := typ.Elem().Kind()
		isElemInterface := elemKind == reflect.Interface
		isElemString := elemKind == reflect.String
		isElemSlice := elemKind == reflect.Slice
		isElemBool := elemKind == reflect.Bool
		isElemInt := elemKind == reflect.Int || elemKind == reflect.Int8 || elemKind == reflect.Int16 || elemKind == reflect.Int32 || elemKind == reflect.Int64
		isElemUint := elemKind == reflect.Uint || elemKind == reflect.Uint8 || elemKind == reflect.Uint16 || elemKind == reflect.Uint32 || elemKind == reflect.Uint64
		isElemFloat := elemKind == reflect.Float32 || elemKind == reflect.Float64
		isElemTime := elemKind == reflect.Struct && typ.Elem().PkgPath() == "time" && typ.Elem().Name() == "Time"
		isElemJSONNumber := elemKind == reflect.Struct && typ.Elem().PkgPath() == "encoding/json" && typ.Elem().Name() == "Number"
		if !(isElemString || isElemInterface || isElemSlice || isElemBool || isElemInt || isElemUint || isElemFloat || isElemTime || isElemJSONNumber) {
			return errors.New("binding element must be a struct")
		}

		if val.IsNil() {
			val.Set(reflect.MakeMap(typ))
		}

		for k, v := range data {
			// If the value is a slice, bind the whole slice. Otherwise bind the first value.
			if isElemSlice {
				slice := reflect.MakeSlice(typ.Elem(), len(v), len(v))
				for i := 0; i < len(v); i++ {
					if err := setWithProperType(typ.Elem().Elem().Kind(), v[i], slice.Index(i)); err != nil {
						return err
					}
				}
				val.SetMapIndex(reflect.ValueOf(k), slice)
			} else if isElemInterface {
				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
			} else {
				elem := reflect.New(typ.Elem()).Elem()
				if err := setWithProperType(elemKind, v[0], elem); err != nil {
					return err
				}
				val.SetMapIndex(reflect.ValueOf(k), elem)
			}
		}
		return nil
	}
