func TestZZTmpBindDataToMapFull(t *testing.T) {
	e := echo.New()
	req := httptest.NewRequest(http.MethodGet, "/?a=1&a=2&b=3", nil)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)

	// map[string][]string
	m1 := map[string][]string{}
	if err := e.Binder.Bind(c, &m1); err != nil {
		t.Fatalf("map[string][]string: %v", err)
	}
	if !reflect.DeepEqual(m1, map[string][]string{"a": {"1", "2"}, "b": {"3"}}) {
		t.Fatalf("map[string][]string got %#v", m1)
	}

	// map[string]string
	m2 := map[string]string{}
	if err := e.Binder.Bind(c, &m2); err != nil {
		t.Fatalf("map[string]string: %v", err)
	}
	if !reflect.DeepEqual(m2, map[string]string{"a": "1", "b": "3"}) {
		t.Fatalf("map[string]string got %#v", m2)
	}

	// map[string]interface{}
	m3 := map[string]interface{}{}
	if err := e.Binder.Bind(c, &m3); err != nil {
		t.Fatalf("map[string]interface{}: %v", err)
	}
	if !reflect.DeepEqual(m3, map[string]interface{}{"a": []string{"1", "2"}, "b": []string{"3"}}) {
		t.Fatalf("map[string]interface{} got %#v", m3)
	}

	// map[string]int
	m4 := map[string]int{}
	if err := e.Binder.Bind(c, &m4); err != nil {
		t.Fatalf("map[string]int: %v", err)
	}
	if !reflect.DeepEqual(m4, map[string]int{"a": 1, "b": 3}) {
		t.Fatalf("map[string]int got %#v", m4)
	}

	// map[string][]int
	m5 := map[string][]int{}
	if err := e.Binder.Bind(c, &m5); err != nil {
		t.Fatalf("map[string][]int: %v", err)
	}
	if !reflect.DeepEqual(m5, map[string][]int{"a": {1, 2}, "b": {3}}) {
		t.Fatalf("map[string][]int got %#v", m5)
	}

	// map[string]bool
	reqB := httptest.NewRequest(http.MethodGet, "/?a=true&b=false", nil)
	cB := e.NewContext(reqB, httptest.NewRecorder())
	m6 := map[string]bool{}
	if err := e.Binder.Bind(cB, &m6); err != nil {
		t.Fatalf("map[string]bool: %v", err)
	}
	if !reflect.DeepEqual(m6, map[string]bool{"a": true, "b": false}) {
		t.Fatalf("map[string]bool got %#v", m6)
	}

	// map[string]float64
	reqF := httptest.NewRequest(http.MethodGet, "/?a=1.5&b=3", nil)
	cF := e.NewContext(reqF, httptest.NewRecorder())
	m7 := map[string]float64{}
	if err := e.Binder.Bind(cF, &m7); err != nil {
		t.Fatalf("map[string]float64: %v", err)
	}
	if !reflect.DeepEqual(m7, map[string]float64{"a": 1.5, "b": 3}) {
		t.Fatalf("map[string]float64 got %#v", m7)
	}

	// map[string]time.Time
	ts := "2021-01-02T15:04:05Z"
	reqT := httptest.NewRequest(http.MethodGet, "/?a="+ts, nil)
	cT := e.NewContext(reqT, httptest.NewRecorder())
	m8 := map[string]time.Time{}
	if err := e.Binder.Bind(cT, &m8); err != nil {
		t.Fatalf("map[string]time.Time: %v", err)
	}
	want8, _ := time.Parse(time.RFC3339, ts)
	if !reflect.DeepEqual(m8, map[string]time.Time{"a": want8}) {
		t.Fatalf("map[string]time.Time got %#v", m8)
	}

	// map[string]json.Number
	reqJ := httptest.NewRequest(http.MethodGet, "/?a=1&b=3", nil)
	cJ := e.NewContext(reqJ, httptest.NewRecorder())
	m9 := map[string]json.Number{}
	if err := e.Binder.Bind(cJ, &m9); err != nil {
		t.Fatalf("map[string]json.Number: %v", err)
	}
	if !reflect.DeepEqual(m9, map[string]json.Number{"a": json.Number("1"), "b": json.Number("3")}) {
		t.Fatalf("map[string]json.Number got %#v", m9)
	}

	// nil map[string][]string must be populated, not panic
	var m10 map[string][]string
	if err := e.Binder.Bind(c, &m10); err != nil {
		t.Fatalf("nil map[string][]string: %v", err)
	}
	if !reflect.DeepEqual(m10, map[string][]string{"a": {"1", "2"}, "b": {"3"}}) {
		t.Fatalf("nil map[string][]string got %#v", m10)
	}

	// map[int]string must error, not panic
	m11 := map[int]string{}
	if err := e.Binder.Bind(c, &m11); err == nil {
		t.Fatalf("map[int]string expected error, got nil")
	}

	// map[string]struct{X int} must error
	m12 := map[string]struct{ X int }{}
	if err := e.Binder.Bind(c, &m12); err == nil {
		t.Fatalf("map[string]struct expected error, got nil")
	}
}

